// Compares texts generated by the original and the adaptive algorithms
// on a downloaded typing-data.json:
//   REPLAY=~/Downloads/typing-data.json npx tstest --import=@keybr/test-env-bundler --test tools/compare.test.ts
import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import { test } from "node:test";
import { Geometry, Language, Layout, loadKeyboard } from "@keybr/keyboard";
import { loadModelSync } from "@keybr/phonetic-model/lib/fs-load.ts";
import { LCG } from "@keybr/rand";
import { makeKeyStatsMap, Result, TextType } from "@keybr/result";
import { Settings } from "@keybr/settings";
import { Histogram } from "@keybr/textinput";
import { geometryDifficulty } from "../lib/bigrams.ts";
import { GuidedLesson } from "../lib/guided.ts";
import { lessonProps } from "../lib/settings.ts";

test("compare generated texts", () => {
  const json = JSON.parse(readFileSync(process.env.REPLAY!, "utf8"));
  const results = json.map(
    (r: any) =>
      new Result(
        Layout.ALL.get(r.layout),
        TextType.ALL.get(r.textType),
        Date.parse(r.timeStamp),
        r.length,
        r.time,
        r.errors,
        new Histogram(r.histogram),
      ),
  );
  const keyboard = loadKeyboard(Layout.RU_RU, Geometry.EYELASH_CORNE);
  const { model } = loadModelSync(Language.RU);
  const words = JSON.parse(
    readFileSync(
      resolve(
        import.meta.dirname,
        "../../keybr-content-words/lib/data/words-ru.json",
      ),
      "utf8",
    ),
  );
  // The weakest keys by speed and errors in the data: и с м я к у.
  const weak = new Set([..."исмяку"]);
  for (const adaptive of [false, true]) {
    const lesson = new GuidedLesson(
      new Settings().set(lessonProps.guided.adaptive, adaptive),
      keyboard,
      model,
      words,
    );
    const lessonKeys = lesson.update(
      makeKeyStatsMap(lesson.letters, results),
    );
    const rng = LCG(7);
    let letters = 0;
    let weakLetters = 0;
    let pairs = 0;
    let hardPairs = 0;
    const counts = new Map<string, number>();
    const all: string[] = [];
    for (let i = 0; i < 200; i++) {
      for (const word of String(lesson.generate(lessonKeys, rng)).split(" ")) {
        all.push(word);
        for (const c of word) {
          letters++;
          if (weak.has(c)) weakLetters++;
          counts.set(c, (counts.get(c) ?? 0) + 1);
        }
        for (let j = 1; j < word.length; j++) {
          pairs++;
          const d = geometryDifficulty(
            keyboard,
            word.codePointAt(j - 1)!,
            word.codePointAt(j)!,
          );
          if (d >= 0.5) hardPairs++;
        }
      }
    }
    const unique = new Set(all).size;
    const focus = lessonKeys.findFocusedKey()?.letter.label;
    const share = (c: string) =>
      (((counts.get(c) ?? 0) / letters) * 100).toFixed(1);
    console.log(
      `adaptive=${adaptive} focus=${focus} words=${all.length} unique=${unique}` +
        ` (${((unique / all.length) * 100).toFixed(0)}%)` +
        ` weakLetters=${((weakLetters / letters) * 100).toFixed(1)}%` +
        ` hardPairs=${((hardPairs / pairs) * 100).toFixed(1)}%` +
        ` и=${share("и")}% с=${share("с")}% м=${share("м")}% я=${share("я")}% к=${share("к")}%` +
        ` avgLen=${(letters / all.length).toFixed(1)}`,
    );
  }
});
